def flip_case(string: str) -> str:
    """ Change every lowercase letter to uppercase and every uppercase letter to lowercase.
    >>> flip_case('Hello')
    'hELLO'

    Handle an empty string by returning an empty string.
    """
    result = ""
    for char in string:
        if char.islower():
            result += char.upper()
        elif char.isupper():
            result += char.lower()
        else:
            result += char
    return result

